export function zip(parts,{deflate=false}={}){const local=[],central=[];let offset=0;for(const[path,text]of Object.entries(parts)){const filename=Buffer.from(path),raw=Buffer.from(text),data=deflate?deflateRawSync(raw):raw,crc=crc32(raw),method=deflate?8:0;const l=Buffer.alloc(30);l.writeUInt32LE(0x04034b50);l.writeUInt16LE(20,4);l.writeUInt16LE(method,8);l.writeUInt32LE(crc,14);l.writeUInt32LE(data.length,18);l.writeUInt32LE(raw.length,22);l.writeUInt16LE(filename.length,26);const c=Buffer.alloc(46);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt16LE(method,10);c.writeUInt32LE(crc,16);c.writeUInt32LE(data.length,20);c.writeUInt32LE(raw.length,24);c.writeUInt16LE(filename.length,28);c.writeUInt32LE(offset,42);local.push(l,filename,data);central.push(c,filename);offset+=l.length+filename.length+data.length;}const centralBuffer=Buffer.concat(central),e=Buffer.alloc(22);e.writeUInt32LE(0x06054b50);e.writeUInt16LE(local.length/3,8);e.writeUInt16LE(local.length/3,10);e.writeUInt32LE(centralBuffer.length,12);e.writeUInt32LE(offset,16);return Buffer.concat([...local,centralBuffer,e]);}
